Definition IB_STACK : Z := 64 + ICOMMIT_STACK.

Definition ib_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (n : Z) (ns' : NS) (lo shi : Z) (X : list Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz n) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (ibW lo (bv_unsigned sp) X) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ ANSR m' ns' X
    /\ ACONST m' /\ stack0 m' lo shi.

Definition ib_stmt : Prop := forall (h pos n : Z) (ns ns' : NS) (fuel : nat) (lo shi : Z) (X : list Z)
    ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ANSR m ns X -> is_Some (ns !! h) -> is_Some (ns !! pos) -> is_Some (ns !! n) ->
  rb_insert_before fuel ns h pos n = Some ns' ->
  stk asegs m lo (bv_unsigned sp) -> lo + IB_STACK <= bv_unsigned sp -> aceil <= lo ->        (* [comment removed for export] *)
  mem_inv asegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  shvis m n (n + 32) ->
  evt asegs (ib_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc n ns' lo shi X m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz h) (wz pos) (wz n) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_RB_INSERT_BEFORE) fc None m (seg_rom asegs)).
