  0 <= h < 2^64 -> 0 <= pos < 2^64 -> 0 <= n < 2^64 ->
  bv_unsigned sp mod 16 = 0 -> XAcc m X -> bv_unsigned sp <= shi ->
  aside m lo shi [] [(n, 32)] ->
  evt asegs (ib_post ra sp gp tp s0v s1v s2v s3v s4 s5 s6 s7 s8 s9 s10 s11 F fc n ns' lo shi X m)
    (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (Z_to_bv 64 n) (Z_to_bv 64 h) (Z_to_bv 64 prev) a1 a2 a3 a4 a5 a6 a7
